import React, { createContext, useContext, useEffect, useState } from 'react';
import API from '../services/api';

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [user, setUser] = useState(() => {
    try {
      const stored = localStorage.getItem('auth_user');
      return stored ? JSON.parse(stored) : null;
    } catch {
      return null;
    }
  });

  const loginUser = (userData) => {
    setUser(userData);
    localStorage.setItem('auth_user', JSON.stringify(userData));
  };

  const logoutUser = () => {
    setUser(null);
    localStorage.removeItem('auth_user');
  };

  useEffect(() => {
    let mounted = true;
    const storedAtSyncStart = localStorage.getItem('auth_user');
    console.log('[RULE-TRACE][AUTH] /me start', {
      at: performance.now().toFixed(1),
      storedUser: storedAtSyncStart,
    });
    API.get('/me/')
      .then((res) => {
        if (!mounted) return;
        const serverUser = res.data?.data;
        console.log('[RULE-TRACE][AUTH] /me success', {
          at: performance.now().toFixed(1),
          serverUser,
        });
        if (serverUser) {
          setUser(serverUser);
          localStorage.setItem('auth_user', JSON.stringify(serverUser));
        }
      })
      .catch((err) => {
        if (!mounted) return;
        console.log('[RULE-TRACE][AUTH] /me error', {
          at: performance.now().toFixed(1),
          status: err?.response?.status,
          error: err?.response?.data?.error || err.message,
        });
        if (err?.response?.status === 401) {
          if (localStorage.getItem('auth_user') === storedAtSyncStart) {
            setUser(null);
            localStorage.removeItem('auth_user');
          }
        }
      });
    return () => { mounted = false; };
  }, []);

  return (
    <AuthContext.Provider value={{ user, loginUser, logoutUser }}>
      {children}
    </AuthContext.Provider>
  );
}

export const useAuth = () => useContext(AuthContext);

import React, { createContext, useCallback, useContext, useEffect, useState } from 'react';
import { translations } from '../i18n/translations';

const I18nContext = createContext(null);

const STORAGE_KEY = 'app-lang';

function getInitialLang() {
  const stored = window.localStorage.getItem(STORAGE_KEY);
  return stored === 'ar' ? 'ar' : 'en';
}

export function I18nProvider({ children }) {
  const [lang, setLangState] = useState(getInitialLang);

  const setLang = (next) => {
    setLangState(next);
    window.localStorage.setItem(STORAGE_KEY, next);
  };

  useEffect(() => {
    document.documentElement.dir  = lang === 'ar' ? 'rtl' : 'ltr';
    document.documentElement.lang = lang;
  }, [lang]);

  // t('wizard.step1')  or  t('common.save')
  const t = useCallback((path, ...args) => {
    if (!path || typeof path !== 'string') return '';
    const keys = path.split('.');
    let node = translations[lang];
    for (const k of keys) {
      if (node == null) return path;
      node = node[k];
    }
    if (typeof node === 'function') return node(...args);
    if (typeof node === 'string') return node;
    return path;
  }, [lang]);

  return (
    <I18nContext.Provider value={{ lang, setLang, t }}>
      {children}
    </I18nContext.Provider>
  );
}

export function useI18n() {
  const ctx = useContext(I18nContext);
  if (!ctx) throw new Error('useI18n must be used inside I18nProvider');
  return ctx;
}

import React, { createContext, useCallback, useContext, useMemo, useState } from 'react';
import { useI18n } from '../../contexts/I18nContext';

const ToastContext = createContext(null);
const DEFAULT_TTL = 4500;

export function ToastProvider({ children }) {
  const { t } = useI18n();
  const [toasts, setToasts] = useState([]);
  const labels = useMemo(() => ({
    success: t('common.success'),
    error: t('common.error'),
    warning: t('common.warning'),
    info: t('common.info'),
  }), [t]);

  const dismiss = useCallback((id) => {
    setToasts((current) => current.filter((toast) => toast.id !== id));
  }, []);

  const show = useCallback(
    (message, type = 'info', options = {}) => {
      const id = `${Date.now()}-${Math.random().toString(36).slice(2)}`;
      const toast = {
        id,
        type,
        message,
        title: options.title || labels[type] || labels.info,
      };

      setToasts((current) => [...current.slice(-4), toast]);

      const ttl = options.ttl ?? DEFAULT_TTL;
      if (ttl !== 0) {
        window.setTimeout(() => dismiss(id), ttl);
      }

      return id;
    },
    [dismiss, labels]
  );

  const value = useMemo(
    () => ({
      show,
      dismiss,
      success: (message, options) => show(message, 'success', options),
      error: (message, options) => show(message, 'error', options),
      warning: (message, options) => show(message, 'warning', options),
      info: (message, options) => show(message, 'info', options),
    }),
    [dismiss, show]
  );

  return (
    <ToastContext.Provider value={value}>
      {children}
      <div className="toast-region" role="status" aria-live="polite" aria-relevant="additions">
        {toasts.map((toast) => (
          <div className={`toast toast--${toast.type}`} key={toast.id}>
            <div className="toast__mark" aria-hidden="true">
              {toast.type === 'success' ? 'OK' : toast.type === 'warning' ? '!' : toast.type === 'error' ? 'X' : 'i'}
            </div>
            <div className="toast__body">
              <strong>{toast.title}</strong>
              <span>{toast.message}</span>
            </div>
            <button type="button" className="toast__close" onClick={() => dismiss(toast.id)} aria-label={t('common.dismissNotification')}>
              x
            </button>
          </div>
        ))}
      </div>
    </ToastContext.Provider>
  );
}

export function useToast() {
  const context = useContext(ToastContext);
  if (!context) {
    throw new Error('useToast must be used inside ToastProvider');
  }
  return context;
}
